{"path": "units/chain/stage3.py", "content": """"Stage 3: aggregate the surviving orders by unit price.

The result maps each distinct ``price`` to the total quantity ordered at that
price, e.g. orders ``(price=10, qty=2)`` and ``(price=7, qty=3)`` plus
``(price=7, qty=1)`` produce ``{10: 2, 7: 4}``.
"""


def total_by_price(rows):
    """Return ``{price: total_qty}`` for the orders in ``rows``."""
    totals = {}
    for row in rows:
        price = row["price"]
        totals[price] = totals.get(price, 0) + row["qty"]
    return totals
"}

{"path": "units/chain/stage4.py", "content": """"Stage 4: render the price totals as the final report text.

Each ``price: total`` pair goes on its own line, sorted by price ascending, and
the report always ends with a trailing newline.  For ``{10: 2, 7: 4}`` the
report is ``"7:4\\n10:2\\n"``.
"""


def report(totals):
    """Return the sorted, newline-terminated text for a ``{price: qty}`` map."""
    return "".join(
        "{0}:{1}\n".format(price, totals[price]) for price in sorted(totals)
    )
"}
